import { precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching';
import { clientsClaim, skipWaiting } from 'workbox-core';
import { registerRoute, NavigationRoute } from 'workbox-routing';
import { CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// OneSignal Integration
// @ts-ignore
importScripts('https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.sw.js');

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Opening any app address offline (/dashboard, a shared link...): the network first, as before, so Netlify
// still serves the right page; with no connection (or one that hangs for 4 s), the app shell from the
// precache, which then opens on the data kept on the device. "/" itself is already served by the precache.
const appShell = createHandlerBoundToURL('/app.html');
registerRoute(new NavigationRoute(async (options) => {
  try {
    return await Promise.race([
      fetch(options.request),
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 4000)),
    ]);
  } catch {
    return appShell(options);
  }
}, {
  // not for Netlify functions or direct links to files (/guide.pdf, /notify/x.jpg...)
  denylist: [/^\/\.netlify\//, /\/[^/?]+\.[a-z0-9]+$/i],
}));

// Google Fonts: the stylesheet refreshes in the background, the font files are kept for a year,
// so text keeps its typeface offline after the first visit
registerRoute(
  ({ url }) => url.origin === 'https://fonts.googleapis.com',
  new StaleWhileRevalidate({ cacheName: 'google-fonts-css' }),
);
registerRoute(
  ({ url }) => url.origin === 'https://fonts.gstatic.com',
  new CacheFirst({
    cacheName: 'google-fonts',
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200] }),
      new ExpirationPlugin({ maxEntries: 40, maxAgeSeconds: 365 * 24 * 60 * 60 }),
    ],
  }),
);

// skipWaiting() makes the new SW activate immediately upon detection,
// bypassing the waiting phase. This ensures that every time you push
// a new deployment, installed PWA users get the update automatically
// on their next page visibility/load — no manual "Update App" tap needed.
skipWaiting();

// clientsClaim() makes the newly active SW take control of all open tabs
// right away, so the updated assets are served immediately.
clientsClaim();
